layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT; if (u < 0. || u > 1.05){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 4.00; vP = position.xy*S; vU = u; vK = aK;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .035, -position.y*S), 1.);
    }

layers.fragment:
uniform vec3 uCW, uCT; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    void main(){
      vec2 p = vP; float r = length(p), a = atan(p.x, p.y), R = 3.60, u = vU - 0.15;
      vec3 col = mix(uCW, uCT, vK);
      float lum = 0., hot = 0.;
      if (u < 0.){
        // wind-up: a small gather at the Root
        float k = vU/0.15; lum += exp(-r*r*14.)*k*k*.5;
      } else {
        lum += exp(-r*r*5.)*(u < .033 ? 1.1 : .4*exp(-u*10.));      // 2-frame snap at the Root
        if (vK < .5){
          // Battlecry: three crests, the middle one strongest, slightly jagged — fast and aggressive
          for (int j=0;j<3;j++){
            float fj = float(j), uj = u - fj*.045;
            if (uj < 0.) continue;
            float rr = eox(clamp(uj/.2, 0., 1.))*R*(1. - .06*fj);
            rr += .035*abs(sin(a*9. + fj*1.3))*smoothstep(.2, 1., rr/R);
            float f = 1. - smoothstep(.12, .3, uj), wgt = fj == 1. ? 1. : .55;
            float w = (.012 + .03*wgt)*(1. - .5*clamp(uj/.3, 0., 1.));
            lum += exp(-pow(abs(r - rr)/w, 2.4))*f*wgt*1.1; hot += lcore(r - rr, w*.3)*f*wgt*.5;
          }
        } else {
          // Challenge: one steady pulse that settles and stays anchored on the area edge
          float rr = eox(clamp(u/.22, 0., 1.))*R, f = 1. - smoothstep(.15, .3, u);
          lum += exp(-pow(abs(r - rr)/.02, 2.4))*f*.9;
          float hold = smoothstep(.16, .24, u)*(1. - smoothstep(.55, .9, u));   // the rim is the last thing to go
          float ring = exp(-pow(abs(r - R)/.016, 2.4));
          float tick = 0.;
          for (int i=0;i<16;i++){
            float th = float(i)*.3927; vec2 d = vec2(sin(th), cos(th));
            float along = dot(p, d), off = abs(p.x*d.y - p.y*d.x);
            tick += exp(-pow(off/.012, 2.))*smoothstep(R - .32, R - .22, along)*smoothstep(R - .04, R - .12, along);
          }
          lum += (ring*.95 + tick*.55)*hold; hot += lcore(r - R, .005)*hold*.5;
        }
      }
      vec3 outc = col*lum + mix(col, vec3(1., .96, .95), .6)*hot;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
